61	// Register persists a normalized SBOM in a single write transaction. When the
62	// same artifact and version already hold an identical manifest, the existing
63	// record (with its original ID) is returned and created is false. Different
64	// content leaves the existing record untouched and returns model.ErrConflict.
65	func (s *Store) Register(ctx context.Context, in *model.SBOM) (sbom *model.SBOM, created bool, err error) {
66		c, err := s.db.Conn(ctx)
67		if err != nil {
68			return nil, false, unavailable(err)
69		}
70		defer c.Close()
71	
72		// BEGIN IMMEDIATE takes the writer lock up front, so two concurrent
73		// registrations for the same artifact/version serialize and the loser
74		// re-reads the winner's committed row instead of hitting the unique
75		// constraint.
76		if _, err := c.ExecContext(ctx, "BEGIN IMMEDIATE"); err != nil {
77			return nil, false, unavailable(err)
78		}
79		committed := false
80		defer func() {
81			if !committed {
82				// Best-effort cleanup; the original error is what callers need.
83				_, _ = c.ExecContext(context.Background(), "ROLLBACK")
84			}
85		}()
86	
87		var existingID int64
88		switch err := c.QueryRowContext(ctx,
89			"SELECT id FROM sboms WHERE artifact = ? AND version = ?",
90			in.Artifact, in.Version,
91		).Scan(&existingID); {
92		case err == nil:
93			existing, err := loadSBOM(ctx, c, existingID)
94			if err != nil {
95				return nil, false, err
96			}
97			if !equalContent(existing, in) {
98				return nil, false, model.ErrConflict
99			}
100			return existing, false, nil
101		case errors.Is(err, sql.ErrNoRows):
102			// Continue and insert.
103		default:
104			return nil, false, unavailable(err)
105		}
106	
107		res, err := c.ExecContext(ctx,
108			"INSERT INTO sboms (artifact, version) VALUES (?, ?)",
109			in.Artifact, in.Version)
110		if err != nil {
111			return nil, false, unavailable(err)
112		}
113		id, err := res.LastInsertId()
114		if err != nil {
115			return nil, false, unavailable(err)
116		}
117	
118		componentID := make(map[string]int64, len(in.Components))
119		insertComponent, err := c.PrepareContext(ctx,
120			"INSERT INTO components (sbom_id, coordinate, license) VALUES (?, ?, ?)")
121		if err != nil {
122			return nil, false, unavailable(err)
123		}
124		defer insertComponent.Close()
125		for i := range in.Components {
126			comp := &in.Components[i]
127			res, err := insertComponent.ExecContext(ctx, id, comp.Coordinate, comp.License)
128			if err != nil {
129				return nil, false, unavailable(err)
130			}
131			compID, err := res.LastInsertId()
132			if err != nil {
133				return nil, false, unavailable(err)
134			}
135			componentID[comp.Coordinate] = compID
136		}
137	
138		if depCount := countDependencies(in); depCount > 0 {
139			insertDep, err := c.PrepareContext(ctx,
140				"INSERT INTO dependencies (component_id, target_id) VALUES (?, ?)")
141			if err != nil {
142				return nil, false, unavailable(err)
143			}
144			defer insertDep.Close()
145			for i := range in.Components {
146				comp := &in.Components[i]
147				for _, dep := range comp.Dependencies {
148					if _, err := insertDep.ExecContext(ctx, componentID[comp.Coordinate], componentID[dep]); err != nil {
149						return nil, false, unavailable(err)
150					}
151				}
152			}
153		}
154	
155		if _, err := c.ExecContext(ctx, "COMMIT"); err != nil {
156			return nil, false, unavailable(err)
157		}
158		committed = true
159	
160		out := *in
161		out.ID = id
162		return &out, true, nil
163	}
