165	// List returns one page of complete SBOMs for an artifact ordered by ID, plus
166	// the total number of matching manifests. Both reads run in one transaction so
167	// the count and the page share the same snapshot.
168	func (s *Store) List(ctx context.Context, artifact string, page, pageSize int) (items []*model.SBOM, total int, err error) {
169		tx, err := s.db.BeginTx(ctx, nil)
170		if err != nil {
171			return nil, 0, unavailable(err)
172		}
173		defer tx.Rollback()
174	
175		if err := tx.QueryRowContext(ctx,
176			"SELECT COUNT(*) FROM sboms WHERE artifact = ?", artifact,
177		).Scan(&total); err != nil {
178			return nil, 0, unavailable(err)
179		}
180	
181		rows, err := tx.QueryContext(ctx,
182			"SELECT id FROM sboms WHERE artifact = ? ORDER BY id ASC LIMIT ? OFFSET ?",
183			artifact, pageSize, (page-1)*pageSize)
184		if err != nil {
185			return nil, 0, unavailable(err)
186		}
187		defer rows.Close()
188	
189		items = []*model.SBOM{}
190		for rows.Next() {
191			var id int64
192			if err := rows.Scan(&id); err != nil {
193				return nil, 0, unavailable(err)
194			}
195			sbom, err := loadSBOM(ctx, tx, id)
196			if err != nil {
197				return nil, 0, err
198			}
199			items = append(items, sbom)
200		}
201		if err := rows.Err(); err != nil {
202			return nil, 0, unavailable(err)
203		}
204		if err := tx.Commit(); err != nil {
205			return nil, 0, unavailable(err)
206		}
207		return items, total, nil
208	}
