210	// loadSBOM reconstructs a full manifest with components ordered by coordinate
211	// and each component's dependencies ordered by the target coordinate.
212	func loadSBOM(ctx context.Context, q queryer, id int64) (*model.SBOM, error) {
213		sbom := &model.SBOM{ID: id, Components: []model.Component{}}
214		if err := q.QueryRowContext(ctx,
215			"SELECT artifact, version FROM sboms WHERE id = ?", id,
216		).Scan(&sbom.Artifact, &sbom.Version); err != nil {
217			return nil, unavailable(err)
218		}
219	
220		componentRows, err := q.QueryContext(ctx,
221			"SELECT coordinate, license FROM components WHERE sbom_id = ? ORDER BY coordinate ASC", id)
222		if err != nil {
223			return nil, unavailable(err)
224		}
225		defer componentRows.Close()
226	
227		indexByCoordinate := make(map[string]int)
228		for componentRows.Next() {
229			var comp model.Component
230			comp.Dependencies = []string{}
231			if err := componentRows.Scan(&comp.Coordinate, &comp.License); err != nil {
232				return nil, unavailable(err)
233			}
234			indexByCoordinate[comp.Coordinate] = len(sbom.Components)
235			sbom.Components = append(sbom.Components, comp)
236		}
237		if err := componentRows.Err(); err != nil {
238			return nil, unavailable(err)
239		}
240	
241		depRows, err := q.QueryContext(ctx, `
242	SELECT sc.coordinate, tc.coordinate
243	FROM dependencies d
244	JOIN components sc ON sc.id = d.component_id
245	JOIN components tc ON tc.id = d.target_id
246	WHERE sc.sbom_id = ?
247	ORDER BY sc.coordinate ASC, tc.coordinate ASC`, id)
248		if err != nil {
249			return nil, unavailable(err)
250		}
251		defer depRows.Close()
252	
253		for depRows.Next() {
254			var from, to string
255			if err := depRows.Scan(&from, &to); err != nil {
256				return nil, unavailable(err)
257			}
258			comp := &sbom.Components[indexByCoordinate[from]]
259			comp.Dependencies = append(comp.Dependencies, to)
260		}
261		if err := depRows.Err(); err != nil {
262			return nil, unavailable(err)
263		}
264		return sbom, nil
265	}
266	
267	// equalContent compares normalized manifests (sorted components and
268	// dependencies); artifact and version already matched in SQL.
269	func equalContent(a, b *model.SBOM) bool {
270		if len(a.Components) != len(b.Components) {
271			return false
272		}
273		for i := range a.Components {
274			x, y := &a.Components[i], &b.Components[i]
275			if x.Coordinate != y.Coordinate || x.License != y.License {
276				return false
277			}
278			if len(x.Dependencies) != len(y.Dependencies) {
279				return false
280			}
281			for j := range x.Dependencies {
282				if x.Dependencies[j] != y.Dependencies[j] {
283					return false
284				}
285			}
286		}
287		return true
288	}
289	
290	func countDependencies(in *model.SBOM) int {
291		n := 0
292		for i := range in.Components {
293			n += len(in.Components[i].Dependencies)
294		}
295		return n
296	}
297	
298	func unavailable(err error) error {
299		if errors.Is(err, model.ErrStorageUnavailable) {
300			return err
301		}
302		return fmt.Errorf("%w: %v", model.ErrStorageUnavailable, err)
303	}
304	
305	const schema = `
306	CREATE TABLE IF NOT EXISTS service_metadata (
307	    key   TEXT PRIMARY KEY,
308	    value TEXT NOT NULL
309	);
310	CREATE TABLE IF NOT EXISTS sboms (
311	    id       INTEGER PRIMARY KEY,
312	    artifact TEXT NOT NULL,
313	    version  TEXT NOT NULL,
314	    UNIQUE (artifact, version)
315	);
316	CREATE TABLE IF NOT EXISTS components (
317	    id         INTEGER PRIMARY KEY,
318	    sbom_id    INTEGER NOT NULL REFERENCES sboms(id) ON DELETE CASCADE,
319	    coordinate TEXT NOT NULL,
320	    license    TEXT NOT NULL,
321	    UNIQUE (sbom_id, coordinate)
322	);
323	CREATE TABLE IF NOT EXISTS dependencies (
324	    id           INTEGER PRIMARY KEY,
325	    component_id INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
326	    target_id    INTEGER NOT NULL REFERENCES components(id) ON DELETE CASCADE,
327	    UNIQUE (component_id, target_id)
328	);
