29	func postSBOM(t *testing.T, router *gin.Engine, body string) *httptest.ResponseRecorder {
30		t.Helper()
31		req := httptest.NewRequest(http.MethodPost, "/sboms", bytes.NewReader([]byte(body)))
32		req.Header.Set("Content-Type", "application/json")
33		rec := httptest.NewRecorder()
34		router.ServeHTTP(rec, req)
35		return rec
36	}
37	
38	func getSBOMs(t *testing.T, router *gin.Engine, target string) *httptest.ResponseRecorder {
39		t.Helper()
40		req := httptest.NewRequest(http.MethodGet, target, nil)
41		rec := httptest.NewRecorder()
42		router.ServeHTTP(rec, req)
43		return rec
44	}
45	
46	func decodeBody(t *testing.T, rec *httptest.ResponseRecorder, v any) {
47		t.Helper()
48		if err := json.Unmarshal(rec.Body.Bytes(), v); err != nil {
49			t.Fatalf("decode %q: %v", rec.Body.String(), err)
50		}
51	}
52	
53	func expectError(t *testing.T, rec *httptest.ResponseRecorder, status int, code string) {
54		t.Helper()
55		if rec.Code != status {
56			t.Fatalf("status = %d, want %d; body %s", rec.Code, status, rec.Body.String())
57		}
58		var envelope struct {
59			Error struct {
60				Code    string `json:"code"`
61				Message string `json:"message"`
62			} `json:"error"`
63		}
64		decodeBody(t, rec, &envelope)
65		if envelope.Error.Code != code {
66			t.Fatalf("code = %q, want %q", envelope.Error.Code, code)
67		}
68		if envelope.Error.Message == "" {
69			t.Fatalf("error message is empty")
70		}
71		for _, leaked := range []string{"SQLITE", "sql:", "goroutine", "/", ".go:"} {
72			if bytes.Contains(rec.Body.Bytes(), []byte(leaked)) {
73				t.Fatalf("error response leaks %q: %s", leaked, rec.Body.String())
74			}
75		}
76	}
