78	func TestRegisterCreatesNormalizedManifest(t *testing.T) {
79		router, _ := newTestRouter(t)
80	
81		// Whitespace everywhere, components and dependencies in non-sorted order.
82		body := `{
83			"artifact": "  atlas  ",
84			"version": " 1.2.0 ",
85			"components": [
86				{"coordinate": " lib-z ", "license": " MIT ", "dependencies": [" lib-a "]},
87				{"coordinate": "lib-a", "license": "Apache-2.0", "dependencies": []}
88			]
89		}`
90		rec := postSBOM(t, router, body)
91		if rec.Code != http.StatusCreated {
92			t.Fatalf("status = %d, body %s", rec.Code, rec.Body.String())
93		}
94		var got model.SBOM
95		decodeBody(t, rec, &got)
96		if got.ID <= 0 {
97			t.Fatalf("id = %d, want positive integer", got.ID)
98		}
99		want := model.SBOM{
100			ID:       got.ID,
101			Artifact: "atlas",
102			Version:  "1.2.0",
103			Components: []model.Component{
104				{Coordinate: "lib-a", License: "Apache-2.0", Dependencies: []string{}},
105				{Coordinate: "lib-z", License: "MIT", Dependencies: []string{"lib-a"}},
