		sbom, err := loadSBOM(ctx, tx, id)
		if err != nil {
			return nil, 0, err
		}
		items = append(items, sbom)
	}
	if err := rows.Err(); err != nil {
		return nil, 0, unavailable(err)
	}
	if err := tx.Commit(); err != nil {
		return nil, 0, unavailable(err)
	}
	return items, total, nil
}

