			t.Fatalf("shared license in %s = %q, want %q", version, shared.License, license)
		}
		wantDep := "only-" + version
		if len(shared.Dependencies) != 1 || shared.Dependencies[0] != wantDep {
			t.Fatalf("shared deps in %s = %v, want [%s]", version, shared.Dependencies, wantDep)
		}
		ownLeaf, ok := byVersion[version][wantDep]
		if !ok {
			t.Fatalf("version %s missing its own leaf component", version)
		}
		if len(ownLeaf.Dependencies) != 1 || ownLeaf.Dependencies[0] != "shared" {
			t.Fatalf("leaf deps in %s = %v, want [shared]", version, ownLeaf.Dependencies)
		}
