		body := fmt.Sprintf(`{"artifact":"app","version":"%s","components":[
			{"coordinate":"shared","license":"%s","dependencies":["%s"]},
			{"coordinate":"only-%s","license":"L","dependencies":[]},
			{"coordinate":"%s","license":"L","dependencies":["shared"]}
		]}`, version, license, dep, version, dep)
		if rec := postSBOM(t, router, body); rec.Code != http.StatusCreated {
			t.Fatalf("register %s: %d %s", version, rec.Code, rec.Body.String())
		}
	}
	register("v1", "license-v1", "only-v1")
	register("v2", "license-v2", "only-v2")

	rec := getSBOMs(t, router, "/sboms?artifact=app")
	if rec.Code != http.StatusOK {
		t.Fatalf("list: %d %s", rec.Code, rec.Body.String())
	}
	var got listResponse
	decodeBody(t, rec, &got)
	if got.Total != 2 || len(got.Items) != 2 {
		t.Fatalf("total/items = %d/%d, want 2/2", got.Total, len(got.Items))
	}

	byVersion := map[string]map[string]model.Component{}
	for _, item := range got.Items {
		comps := map[string]model.Component{}
		for _, comp := range item.Components {
			comps[comp.Coordinate] = comp
		}
		byVersion[item.Version] = comps
	}
	for version, license := range map[string]string{"v1": "license-v1", "v2": "license-v2"} {
		shared, ok := byVersion[version]["shared"]
		if !ok {
			t.Fatalf("version %s missing shared component", version)
		}
		if shared.License != license {
			t.Fatalf("shared license in %s = %q, want %q", version, shared.License, license)
		}
		wantDep := "only-" + version
		if len(shared.Dependencies) != 1 || shared.Dependencies[0] != wantDep {
			t.Fatalf("shared deps in %s = %v, want [%s]", version, shared.Dependencies, wantDep)
		}
		ownLeaf, ok := byVersion[version][wantDep]
		if !ok {
			t.Fatalf("version %s missing its own leaf component", version)
		}
		if len(ownLeaf.Dependencies) != 1 || ownLeaf.Dependencies[0] != "shared" {
			t.Fatalf("leaf deps in %s = %v, want [shared]", version, ownLeaf.Dependencies)
		}
		if _, leaked := byVersion[version]["only-"+otherVersion(version)]; leaked {
			t.Fatalf("version %s leaked the other version's leaf into its components", version)
		}
		// And the shared component's dependency edge must not have picked up the
		// other version's target.
		for _, dep := range shared.Dependencies {
			if dep == "only-"+otherVersion(version) {
				t.Fatalf("shared dep in %s crossed into another version", version)
			}
		}
	}
}

func otherVersion(v string) string {
	if v == "v1" {
		return "v2"
	}
	return "v1"
}

