30	// --- SELECT counting through a wrapped database/sql/driver ------------------
31	//
32	// The counter sits below database/sql, on the actual driver connection, so it
33	// observes the SQL statements the store really sends. It cannot be satisfied by
34	// an internal function being called or by cached results.
35	
36	type selectCall struct {
37		query string
38		args  []any
39	}
40	
41	type queryCounter struct {
42		mu      sync.Mutex
43		selects []selectCall
44	}
45	
46	func (q *queryCounter) record(query string, args []driver.NamedValue) {
47		if !strings.HasPrefix(strings.ToUpper(strings.TrimSpace(query)), "SELECT") {
48			return
49		}
50		values := make([]any, len(args))
51		for i, arg := range args {
52			values[i] = arg.Value
53		}
54		q.mu.Lock()
55		q.selects = append(q.selects, selectCall{query: query, args: values})
56		q.mu.Unlock()
57	}
58	
59	func (q *queryCounter) reset() {
60		q.mu.Lock()
61		q.selects = nil
62		q.mu.Unlock()
63	}
64	
65	func (q *queryCounter) calls() []selectCall {
66		q.mu.Lock()
67		defer q.mu.Unlock()
68		out := make([]selectCall, len(q.selects))
69		copy(out, q.selects)
70		return out
71	}
72	
73	// dsnConnector opens fresh driver connections for a fixed DSN.
74	type dsnConnector struct {
75		drv driver.Driver
76		dsn string
77	}
78	
79	func (c dsnConnector) Connect(context.Context) (driver.Conn, error) { return c.drv.Open(c.dsn) }
80	func (c dsnConnector) Driver() driver.Driver                        { return c.drv }
81	
82	type countingConnector struct {
83		inner driver.Connector
84		qc    *queryCounter
85	}
86	
87	func (c countingConnector) Connect(ctx context.Context) (driver.Conn, error) {
88		conn, err := c.inner.Connect(ctx)
89		if err != nil {
90			return nil, err
91		}
92		return &countingConn{Conn: conn, qc: c.qc}, nil
93	}
94	
95	func (c countingConnector) Driver() driver.Driver { return c.inner.Driver() }
96	
97	// countingConn only intercepts the context query/exec entry points the store
98	// uses; transaction control and everything else pass through unchanged.
99	type countingConn struct {
100		driver.Conn
101		qc *queryCounter
102	}
103	
104	func (c *countingConn) PrepareContext(ctx context.Context, query string) (driver.Stmt, error) {
105		if pc, ok := c.Conn.(driver.ConnPrepareContext); ok {
106			return pc.PrepareContext(ctx, query)
107		}
108		return c.Conn.Prepare(query)
109	}
110	
111	func (c *countingConn) ExecContext(ctx context.Context, query string, args []driver.NamedValue) (driver.Result, error) {
112		c.qc.record(query, args)
113		return c.Conn.(driver.ExecerContext).ExecContext(ctx, query, args)
114	}
115	
116	func (c *countingConn) QueryContext(ctx context.Context, query string, args []driver.NamedValue) (driver.Rows, error) {
117		c.qc.record(query, args)
118		return c.Conn.(driver.QueryerContext).QueryContext(ctx, query, args)
119	}
120	
121	func (c *countingConn) BeginTx(ctx context.Context, opts driver.TxOptions) (driver.Tx, error) {
122		return c.Conn.(driver.ConnBeginTx).BeginTx(ctx, opts)
123	}
124	
125	func (c *countingConn) Ping(ctx context.Context) error {
126		if p, ok := c.Conn.(driver.Pinger); ok {
127			return p.Ping(ctx)
128		}
129		return nil
130	}
131	
132	// openCountingStore returns a store whose driver traffic runs through a fresh
133	// counter. The schema and WAL mode are provisioned normally first, so the
134	// counting connection opens an existing, already-migrated database file.
135	func openCountingStore(t *testing.T) (*Store, *queryCounter) {
136		t.Helper()
137		path := filepath.Join(t.TempDir(), "counting.db")
