165	// List returns one page of complete SBOMs for an artifact ordered by ID, plus
166	// the total number of matching manifests. The count, the page's manifests,
167	// their components and their dependencies are four SELECT statements at most,
168	// regardless of page size; the components and dependencies are bulk-loaded for
169	// the current page only. All reads run in one transaction so the count and the
170	// page share one committed snapshot and never expose a half-written manifest.
171	func (s *Store) List(ctx context.Context, artifact string, page, pageSize int) (items []*model.SBOM, total int, err error) {
172		tx, err := s.db.BeginTx(ctx, nil)
173		if err != nil {
174			return nil, 0, unavailable(err)
175		}
176		defer tx.Rollback()
177	
178		// SELECT 1: matching total, independent of the page window.
179		if err := tx.QueryRowContext(ctx,
180			"SELECT COUNT(*) FROM sboms WHERE artifact = ?", artifact,
181		).Scan(&total); err != nil {
182			return nil, 0, unavailable(err)
183		}
184	
185		// SELECT 2: just the manifests of the current page.
186		rows, err := tx.QueryContext(ctx,
187			"SELECT id, artifact, version FROM sboms WHERE artifact = ? ORDER BY id ASC LIMIT ? OFFSET ?",
188			artifact, pageSize, (page-1)*pageSize)
189		if err != nil {
190			return nil, 0, unavailable(err)
191		}
192	
193		items = []*model.SBOM{}
194		ids := make([]int64, 0, pageSize)
195		for rows.Next() {
196			sbom := &model.SBOM{Components: []model.Component{}}
197			if err := rows.Scan(&sbom.ID, &sbom.Artifact, &sbom.Version); err != nil {
198				rows.Close()
199				return nil, 0, unavailable(err)
200			}
201			items = append(items, sbom)
202			ids = append(ids, sbom.ID)
203		}
204		rows.Close()
205		if err := rows.Err(); err != nil {
206			return nil, 0, unavailable(err)
207		}
208	
209		// No ids means an unknown artifact or a page past the last one: the
210		// component and dependency SELECTs are skipped, not run with an empty IN.
211		if len(ids) > 0 {
212			// SELECT 3: every component of every manifest on this page, once.
213			if err := loadComponents(ctx, tx, items, ids); err != nil {
214				return nil, 0, err
215			}
216			// SELECT 4: every dependency edge of every manifest on this page, once.
217			if err := loadDependencies(ctx, tx, items, ids); err != nil {
218				return nil, 0, err
219			}
220		}
221	
222		if err := tx.Commit(); err != nil {
223			return nil, 0, unavailable(err)
224		}
225		return items, total, nil
226	}
227	
228	// loadComponents bulk-loads the components of the page's manifests in a single
229	// SELECT and attaches them coordinate-ordered to their manifest.
230	func loadComponents(ctx context.Context, q queryer, items []*model.SBOM, ids []int64) error {
231		rows, err := q.QueryContext(ctx,
232			"SELECT sbom_id, coordinate, license FROM components WHERE sbom_id IN ("+
233				placeholderList(len(ids))+") ORDER BY sbom_id ASC, coordinate ASC",
234			int64Args(ids)...)
235		if err != nil {
236			return unavailable(err)
237		}
238		defer rows.Close()
239	
240		byID := make(map[int64]int, len(items))
241		for i, sbom := range items {
242			byID[sbom.ID] = i
243		}
244		for rows.Next() {
245			var sbomID int64
246			var comp model.Component
247			comp.Dependencies = []string{}
248			if err := rows.Scan(&sbomID, &comp.Coordinate, &comp.License); err != nil {
249				return unavailable(err)
250			}
251			items[byID[sbomID]].Components = append(items[byID[sbomID]].Components, comp)
252		}
253		if err := rows.Err(); err != nil {
254			return unavailable(err)
255		}
256		return nil
257	}
258	
259	// loadDependencies bulk-loads the dependency edges of the page's manifests in a
260	// single SELECT and attaches the target coordinates to their source component,
261	// ordered by source and target coordinate.
262	func loadDependencies(ctx context.Context, q queryer, items []*model.SBOM, ids []int64) error {
263		rows, err := q.QueryContext(ctx, `
264	SELECT sc.sbom_id, sc.coordinate, tc.coordinate
265	FROM dependencies d
266	JOIN components sc ON sc.id = d.component_id
267	JOIN components tc ON tc.id = d.target_id
268	WHERE sc.sbom_id IN (`+placeholderList(len(ids))+`)
269	ORDER BY sc.sbom_id ASC, sc.coordinate ASC, tc.coordinate ASC`,
270			int64Args(ids)...)
271		if err != nil {
272			return unavailable(err)
273		}
274		defer rows.Close()
275	
276		// One coordinate index per manifest: the same coordinate can legitimately
277		// occur in different versions, and its edges must never cross manifests.
278		coordinateIndex := make([]map[string]int, len(items))
279		for i, sbom := range items {
280			index := make(map[string]int, len(sbom.Components))
281			for j := range sbom.Components {
282				index[sbom.Components[j].Coordinate] = j
283			}
284			coordinateIndex[i] = index
285		}
286		byID := make(map[int64]int, len(items))
287		for i, sbom := range items {
288			byID[sbom.ID] = i
289		}
290		for rows.Next() {
291			var sbomID int64
292			var from, to string
293			if err := rows.Scan(&sbomID, &from, &to); err != nil {
294				return unavailable(err)
295			}
296			itemIndex := byID[sbomID]
297			comp := &items[itemIndex].Components[coordinateIndex[itemIndex][from]]
298			comp.Dependencies = append(comp.Dependencies, to)
299		}
300		if err := rows.Err(); err != nil {
301			return unavailable(err)
302		}
303		return nil
304	}
305	
306	// placeholderList builds "?,?,?" for n bind parameters.
307	func placeholderList(n int) string {
308		return strings.TrimSuffix(strings.Repeat("?,", n), ",")
309	}
310	
311	func int64Args(ids []int64) []any {
312		args := make([]any, len(ids))
313		for i, id := range ids {
314			args[i] = id
315		}
316		return args
317	}
318	
319	// loadSBOM reconstructs a full manifest with components ordered by coordinate
320	// and each component's dependencies ordered by the target coordinate.
321	func loadSBOM(ctx context.Context, q queryer, id int64) (*model.SBOM, error) {
322		sbom := &model.SBOM{ID: id, Components: []model.Component{}}
323		if err := q.QueryRowContext(ctx,
324			"SELECT artifact, version FROM sboms WHERE id = ?", id,
325		).Scan(&sbom.Artifact, &sbom.Version); err != nil {
326			return nil, unavailable(err)
327		}
328	
329		componentRows, err := q.QueryContext(ctx,
330			"SELECT coordinate, license FROM components WHERE sbom_id = ? ORDER BY coordinate ASC", id)
331		if err != nil {
332			return nil, unavailable(err)
333		}
334		defer componentRows.Close()
335	
